1	import { execSync } from 'node:child_process';
2	
3	/**
4	 * Run a WP-CLI command inside the wp-env `cli` container. Throws on non-zero
5	 * exit. Used by tests for deterministic state setup (resetting reports,
6	 * running crons, triggering known events).
7	 */
8	export function wpCli( command: string ): string {
9		const root = `${ __dirname }/../../..`;
10		const cmd = `npx --yes @wordpress/env run cli wp ${ command }`;
11		return execSync( cmd, { cwd: root, encoding: 'utf-8', stdio: [ 'ignore', 'pipe', 'pipe' ] } );
12	}
13	
14	/**
15	 * Run an arbitrary shell command from the repo root. Intended for seed scripts
16	 * and other repo-level tooling.
17	 */
18	export function runFromRepoRoot( command: string ): string {
19		const root = `${ __dirname }/../../..`;
20		return execSync( command, { cwd: root, encoding: 'utf-8', stdio: [ 'ignore', 'pipe', 'pipe' ] } );
21	}
