8	/**
9	 * Smoke tests — issue #46 / EPIC #74.
10	 *
11	 * Each test validates a complete happy-path workflow end-to-end.  They are
12	 * intentionally broad: a failure here signals that a critical user flow is
13	 * broken and warrants deeper investigation via the individual feature specs.
14	 */
15	test.describe( 'Smoke: critical happy-path workflows', () => {
16		test.beforeAll( () => {
17			runFromRepoRoot( 'bin/dev-seed.sh' );
18		} );
19	
20		test.beforeEach( async ( { page } ) => {
21			await loginAsAdmin( page );
22		} );
23	
24		// ------------------------------------------------------------------
25		// 1. Admin login and dashboard access
26		// ------------------------------------------------------------------
27		test( 'admin can log in and see the dashboard with the Sybgo widget', async ( { page } ) => {
28			const widget = new DashboardWidgetPage( page );
29			await widget.goto();
30	
31			await expect( widget.title ).toBeVisible();
32			await expect( widget.root ).toContainText( "This Week's Activity" );
33		} );
34	
35		// ------------------------------------------------------------------
36		// 2. Active report visible on dashboard widget
37		// ------------------------------------------------------------------
38		test( 'active report details link is visible on the dashboard widget', async ( { page } ) => {
39			const widget = new DashboardWidgetPage( page );
40			await widget.goto();
41	
42			await expect( widget.viewThisWeekLink ).toBeVisible();
43		} );
44	
45		// ------------------------------------------------------------------
46		// 3. Report lifecycle: seed → freeze → frozen in list
47		// ------------------------------------------------------------------
48		test( 'freeze workflow produces an active + frozen report visible in the list', async ( { page } ) => {
49			wpCli( 'cron event run sybgo_freeze_weekly_report' );
50	
51			const list = new ReportsListPage( page );
52			await list.goto();
53	
54			const statuses = await list.getAllRowStatuses();
55			expect( statuses ).toContain( 'ACTIVE' );
56			expect( statuses ).toContain( 'FROZEN' );
57		} );
58	
59		// ------------------------------------------------------------------
60		// 4. Email delivery: freeze (0-event report) → email cron → SENT badge
61		//
62		// wp-env has no live SMTP server.  We exercise the "quiet period" code path:
63		// when a frozen report has total_events = 0 and send_empty_reports = false,
64		// Email_Manager::send_report_email() marks the report as emailed without
65		// calling wp_mail().  Full delivery-to-mailbox tests require Mailhog (#75).
66		// ------------------------------------------------------------------
67		test( 'email delivery — quiet period path marks 0-event frozen report as SENT', async ( { page } ) => {
68			// Clear current-period events so the next frozen report has 0 total_events.
69			wpCli( "db query \"DELETE FROM wp_sybgo_events WHERE report_id IS NULL\"" );
70			wpCli( "db query \"DELETE FROM wp_sybgo_aggregated_events WHERE report_id = 0\"" );
71			wpCli( 'cron event run sybgo_freeze_weekly_report' );
72			wpCli( 'cron event run sybgo_send_report_emails' );
73	
74			const list = new ReportsListPage( page );
75			await list.goto();
76	
77			const statuses = await list.getAllRowStatuses();
78			expect( statuses ).toContain( 'SENT' );
79		} );
80	
81		// ------------------------------------------------------------------
82		// 5. Dashboard widget filters
83		// ------------------------------------------------------------------
84		test( 'dashboard widget filter tabs respond to clicks without errors', async ( { page } ) => {
85			const errors: string[] = [];
86			page.on( 'console', ( msg ) => {
87				if ( msg.type() === 'error' ) errors.push( msg.text() );
88			} );
89	
90			const widget = new DashboardWidgetPage( page );
91			await widget.goto();
92	
93			const postsCount = await widget.clickFilterTabAndWait( 'Posts' );
94			expect( typeof postsCount ).toBe( 'number' );
95			expect( postsCount ).toBeGreaterThanOrEqual( 0 );
96	
97			await widget.clickFilterTabAndWait( 'All' );
98			expect( errors ).toHaveLength( 0 );
99		} );
100	
101		// ------------------------------------------------------------------
102		// 6. Error tracking captured and visible on dashboard
103		// ------------------------------------------------------------------
104		test( 'PHP errors tracked via wp eval appear in the dashboard widget', async ( { page } ) => {
105			// Clear current-period errors to get a predictable baseline.
106			wpCli(
107				"db query \"DELETE FROM wp_sybgo_aggregated_events WHERE event_type='php_error' AND report_id IS NULL\""
108			);
109	
110			wpCli( "eval 'trigger_error(\"Sybgo smoke test error\", E_USER_NOTICE);'" );
111	
112			const widget = new DashboardWidgetPage( page );
113			await widget.goto();
114	
115			const errorCount = await widget.getDistinctErrorCount();
116			expect( errorCount ).toBeGreaterThanOrEqual( 1 );
117			await expect( widget.phpErrorsSection ).toBeVisible();
118		} );
119	
120		// ------------------------------------------------------------------
121		// 7. Report detail page accessible from the list
122		// ------------------------------------------------------------------
123		test( 'report detail page is accessible via the View Details link and loads correctly', async ( { page } ) => {
124			const list = new ReportsListPage( page );
125			await list.goto();
126	
127			await list.openDetailsForRow( 0 );
128	
129			const detail = new ReportDetailsPage( page );
130			await detail.expectLoaded();
131			expect( page.url() ).toMatch( /_wpnonce=[a-f0-9]+/ );
132		} );
133	} );
