3	/**
4	 * Page object for the Sybgo Reports list at
5	 * `/wp-admin/admin.php?page=sybgo-reports`.
6	 *
7	 * Source: wp-plugin/admin/class-reports-page.php (render_reports_page list view)
8	 *
9	 * Status badges: ACTIVE, FROZEN, SENT.
10	 * Each row exposes a "View Details" link; active rows expose
11	 * "Freeze & Send Now"; frozen rows expose "Resend Email".
12	 */
13	export class ReportsListPage {
14		readonly page: Page;
15		readonly heading: Locator;
16		readonly table: Locator;
17	
18		constructor( page: Page ) {
19			this.page = page;
20			this.heading = page.getByRole( 'heading', { name: 'Sybgo Reports', exact: true } );
21			this.table = page.locator( '.wrap table' ).first();
22		}
23	
24		async goto(): Promise<void> {
25			await this.page.goto( '/wp-admin/admin.php?page=sybgo-reports' );
26			await expect( this.heading ).toBeVisible();
27		}
28	
29		async row( index: number ): Promise<Locator> {
30			const rows = this.table.locator( 'tbody tr' );
31			await expect( rows.nth( index ) ).toBeVisible();
32			return rows.nth( index );
33		}
34	
35		async getRowCount(): Promise<number> {
36			return this.table.locator( 'tbody tr' ).count();
37		}
38	
39		async getRowStatus( index: number ): Promise<'ACTIVE' | 'FROZEN' | 'SENT'> {
40			const row = await this.row( index );
41			// Status badge is a span with inline styles, typically in the 2nd or 3rd column
42			const badge = await row.locator( 'td span' ).first().innerText();
43			const normalized = badge.trim().toUpperCase();
44			if ( normalized !== 'ACTIVE' && normalized !== 'FROZEN' && normalized !== 'SENT' ) {
45				throw new Error( `Unexpected report status badge: ${ badge }` );
46			}
47			return normalized;
48		}
49	
50		/**
51		 * Return the status of every row in the list, ordered top-to-bottom (newest first).
52		 */
53		async getAllRowStatuses(): Promise<Array<'ACTIVE' | 'FROZEN' | 'SENT'>> {
54			const count = await this.getRowCount();
55			const statuses: Array<'ACTIVE' | 'FROZEN' | 'SENT'> = [];
56			for ( let i = 0; i < count; i++ ) {
57				statuses.push( await this.getRowStatus( i ) );
58			}
59			return statuses;
60		}
61	
62		/**
63		 * Return the 0-based index of the first row whose status matches.
64		 * Throws if no such row is found.
65		 */
66		async findRowIndexByStatus( status: 'ACTIVE' | 'FROZEN' | 'SENT' ): Promise<number> {
67			const count = await this.getRowCount();
68			for ( let i = 0; i < count; i++ ) {
69				if ( ( await this.getRowStatus( i ) ) === status ) {
70					return i;
71				}
72			}
73			throw new Error( `No row with status ${ status } found in reports list` );
74		}
75	
76		async openDetailsForRow( index: number ): Promise<void> {
77			const row = await this.row( index );
78			await row.getByRole( 'link', { name: 'View Details' } ).click();
79			await expect( this.page ).toHaveURL( /view=details/ );
80		}
81	
82		async freezeActiveReport( index: number ): Promise<void> {
83			const row = await this.row( index );
84			await row.getByRole( 'link', { name: /Freeze & Send Now/ } ).click();
85	
86			// Confirmation modal: "Yes, Freeze & Send".
87			await this.page.getByRole( 'button', { name: /Yes, Freeze & Send/ } ).click();
88		}
89	}
